const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let data={stats:{},consultations:[],appointments:[]};const statusNames={new:'Nuevo',progress:'En gestión',closed:'Cerrado',requested:'Solicitada',confirmed:'Confirmada',rescheduled:'Reprogramada',cancelled:'Cancelada',attended:'Atendida',no_show:'No asistió'};function fmt(v){return new Intl.DateTimeFormat('es-CO',{dateStyle:'medium',timeStyle:'short',timeZone:'America/Bogota'}).format(new Date(v))}async function api(path,opt={}){if(!window.AUTH)throw new Error('Inicia sesión para acceder al CRM.');const r=await window.AUTH.request(path,opt);return r}function render(){const q=$('#search').value.toLowerCase(),f=$('#filter').value,rows=data.consultations.filter(x=>(!f||x.status===f)&&(!q||`${x.reference} ${x.name} ${x.problem} ${x.summary}`.toLowerCase().includes(q)));$('#cases').innerHTML=rows.length?rows.map(x=>`<article class="item"><div><b>${esc(x.name)}</b> <span class="badge">${esc(statusNames[x.status]||x.status)}</span><div class="meta">${esc(x.reference)} · ${esc(x.problem)} · ${fmt(x.created_at)}</div><p>${esc(x.summary||'Sin resumen adicional')}</p><div class="meta">${esc(x.email)} · ${esc(x.phone)} · ${x.address?`Dirección: ${esc(x.address)} · `:''}Cita: ${x.scheduled_at?fmt(x.scheduled_at):'sin fecha'} (${esc(statusNames[x.appointment_status]||x.appointment_status||'sin estado')})</div></div><div class="actions"><button data-id="${x.id}" data-type="consultation" data-status="new">Nuevo</button><button data-id="${x.id}" data-type="consultation" data-status="progress">Gestionar</button><button data-id="${x.id}" data-type="consultation" data-status="closed">Cerrar</button></div></article>`).join(''):$('#empty').innerHTML;$('#appointments').innerHTML=data.appointments.length?data.appointments.map(x=>{const status=x.status;const action=(label,next)=>`<button data-id="${esc(x.id)}" data-type="appointment" data-status="${next}">${label}</button>`;return `<article class="item appointment"><div><b>${esc(x.name)}</b> <span class="badge">${esc(statusNames[status]||status)}</span><div class="meta">${esc(x.reference)} · ${fmt(x.scheduled_at)} · ${esc(x.professional)}</div><p>WhatsApp: ${esc(x.phone)}</p></div><div class="actions">${['requested','rescheduled'].includes(status)?action('Confirmar','confirmed'):''}${status==='confirmed'?`<div class="reschedule"><label>Nueva hora en Colombia<input type="datetime-local" data-slot="${esc(x.id)}"></label>${action('Reprogramar','rescheduled')}</div>${action('Atendida','attended')}${action('No asistió','no_show')}`:''}${['requested','confirmed','rescheduled'].includes(status)?action('Cancelar','cancelled'):''}</div></article>`}).join(''):$('#empty').innerHTML;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>change(b));$('#total').textContent=data.stats.total||0;$('#newCount').textContent=data.stats.nuevos||0;$('#closedCount').textContent=data.stats.cerrados||0;$('#appointmentCount').textContent=data.appointments.length}async function load(){const n=$('#notice');n.className='';n.textContent='Actualizando…';try{data=await api('/api/dashboard');render();n.textContent=`Actualizado ${new Date().toLocaleTimeString('es-CO')}`}catch(e){n.className='error';n.textContent=e.message}}async function change(b){b.disabled=true;try{await api(`/api/records/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({type:b.dataset.type,status:b.dataset.status,...(b.dataset.status==='rescheduled'?{scheduled_at:new Date(document.querySelector(`[data-slot=\"${b.dataset.id}\"]`).value+':00-05:00').toISOString()}: {})})});await load()}catch(e){$('#notice').className='error';$('#notice').textContent=e.message;b.disabled=false}}$('#refresh').onclick=load;$('#search').oninput=render;$('#filter').onchange=render;document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x===b));$('#casesView').hidden=b.dataset.view!=='cases';$('#appointmentsView').hidden=b.dataset.view!=='appointments';$('#remindersView').hidden=b.dataset.view!=='reminders';$('#flowView').hidden=b.dataset.view!=='flow';if(b.dataset.view==='flow')window.loadG3Flow();document.querySelectorAll('.tabs button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));if(b.dataset.view==='reminders')window.loadReminders()});window.addEventListener('auth:ready',()=>load());

$('#availabilityForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,values=new FormData(form),date=values.get('date'),start=values.get('start'),end=values.get('end');try{await api('/api/availability',{method:'PUT',body:JSON.stringify({professional:values.get('professional'),date,start_at:new Date(`${date}T${start}:00-05:00`).toISOString(),end_at:new Date(`${date}T${end}:00-05:00`).toISOString()})});$('#notice').className='';$('#notice').textContent='Disponibilidad guardada para '+date}catch(error){$('#notice').className='error';$('#notice').textContent=error.message}};
